def is_palindrome(s):
    return s == s[::-1]


def count_palindromes(words):
    count = 0
    for word in words:
        if is_palindrome(word):
            count += 1
    return count

def find_max(lst):
    if not lst:
        return None
    max_val = lst[0]
    for i in range(1, len(lst)):
        if lst[i] > max_val:
            max_val = lst[i]
    return max_val

